// Package ledger holds the baseline chart of accounts.
//
// It is the single source of truth for those accounts: the onboarding wizard
// seeds them from BaselineChart at runtime, and the demo seed's SQL is
// generated from the same slice by cmd/genseed. Adding an account here is the
// only step needed for both, and the seed test fails if the generated file is
// not refreshed.
package ledger

import (
	"fmt"
	"strings"
)

// Account is one row of the baseline chart of accounts.
type Account struct {
	Code string
	Name string
	Type string // ASSET, LIABILITY, EQUITY, INCOME or EXPENSE
}

// BaselineChart is the minimum a tenant needs before anything can post against
// the ledger: an in-kind intake debits INV_FOOD and credits FEE_RECEIVABLE, and
// is refused with "chart of accounts has no INV_FOOD account" without them.
var BaselineChart = []Account{
	{Code: "INV_FOOD", Name: "Inventory — food", Type: "ASSET"},
	{Code: "FEE_RECEIVABLE", Name: "Fee receivable", Type: "ASSET"},
}

// DemoSeedTenant is the tenant migrations/seed creates.
const DemoSeedTenant = "demo-school"

// SeedSQL renders the seed file that gives the demo tenant the baseline chart.
// ledger_accounts is under FORCE RLS, so the tenant context is set in the same
// statement; the insert is idempotent like the rest of the seed.
func SeedSQL() string {
	var b strings.Builder
	b.WriteString("-- Code generated by backend/cmd/genseed from internal/ledger. DO NOT EDIT.\n")
	b.WriteString("--\n")
	b.WriteString("-- Baseline chart of accounts for the demo tenant. An in-kind intake debits\n")
	b.WriteString("-- INV_FOOD and credits FEE_RECEIVABLE; without these rows it is refused.\n")
	b.WriteString("-- Regenerate with: cd backend && go run ./cmd/genseed\n\n")
	fmt.Fprintf(&b, "SELECT set_config('app.current_tenant_id', '%s', true);\n\n", DemoSeedTenant)
	b.WriteString("INSERT INTO ledger_accounts (tenant_id, code, name, type) VALUES\n")
	for i, account := range BaselineChart {
		sep := ","
		if i == len(BaselineChart)-1 {
			sep = ""
		}
		fmt.Fprintf(&b, "    ('%s', '%s', '%s', '%s')%s\n",
			DemoSeedTenant, account.Code, sqlLiteral(account.Name), account.Type, sep)
	}
	b.WriteString("ON CONFLICT (tenant_id, code) DO NOTHING;\n")
	return b.String()
}

func sqlLiteral(s string) string {
	return strings.ReplaceAll(s, "'", "''")
}
